def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    mod = 1_000_000_007
    size = len(alphabet)
    index = {ch: i for i, ch in enumerate(alphabet)}

    transitions = [[-1] * size]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    failure = [0] * len(transitions)
    queue = []

    for c in range(size):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    head = 0
    while head < len(queue):
        state = queue[head]
        head += 1
        terminal[state] |= terminal[failure[state]]

        for c in range(size):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    valid = [state for state in range(len(transitions)) if not terminal[state]]
    position = {state: i for i, state in enumerate(valid)}
    count = len(valid)

    matrix = [[0] * count for _ in range(count)]
    for state in valid:
        row = matrix[position[state]]
        for target in transitions[state]:
            if not terminal[target]:
                row[position[target]] += 1

    vector = [0] * count
    vector[position[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        if weight:
                            result[j] = (result[j] + value * weight) % mod
            vector = result

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                for k, left in enumerate(matrix[i]):
                    if left:
                        for j, right in enumerate(matrix[k]):
                            if right:
                                squared[i][j] = (
                                    squared[i][j] + left * right
                                ) % mod
            matrix = squared

    return sum(vector) % mod
